  "check_code": "import sqlite3
from pathlib import Path

TARGET_ID = "CAN-2024-017"


def _db_path(ws: str | Path) -> Path:
    return Path(ws).resolve().parent / "system" / "legal_contract_index" / "state.db"


def _row(con: sqlite3.Connection, query: str, params: tuple = ()) -> dict | None:
    con.row_factory = sqlite3.Row
    value = con.execute(query, params).fetchone()
    return dict(value) if value is not None else None


def check_target_disposition(ws):
    with sqlite3.connect(_db_path(ws)) as con:
        row = _row(con, "SELECT candidate_status, candidate_classification FROM legal_lease_candidates WHERE candidate_id = ?", (TARGET_ID,))
    expected = {"candidate_status": "CLOSED", "candidate_classification": "SERVICE_ARRANGEMENT"}
    if row == expected:
        return {"score": 1, "detail": "Target candidate has the required closed service-arrangement disposition."}
    return {"score": 0, "detail": f"Target disposition is {row!r}; expected {expected!r}."}


def check_review_rationale(ws):
    with sqlite3.connect(_db_path(ws)) as con:
        row = _row(con, "SELECT source_reason FROM legal_lease_candidates WHERE candidate_id = ?", (TARGET_ID,))
    rationale = (row or {}).get("source_reason") or ""
    normalized = " ".join(rationale.casefold().split())
    required = {
        "identified asset": "identified-asset basis",
        "substitut": "substitution language",
        "service": "service conclusion",
        "access": "access conclusion",
    }
    missing = [label for token, label in required.items() if token not in normalized]
    reviewer_ok = ("sarah chen" in normalized or "per-sarah-chen" in normalized
                   or "per sarah chen" in normalized)
    exclusive_negative = (
        "exclusive_use_flag=0" in normalized
        or "exclusive use flag=0" in normalized
        or "non-exclusive" in normalized
        or "non exclusive" in normalized
        or "not exclusive" in normalized
        or "no exclusive use" in normalized
    )
    if not reviewer_ok:
        missing.insert(0, "reviewer Sarah Chen")
    if not exclusive_negative:
        missing.append("exclusive-use basis")
    if not missing:
        return {"score": 1, "detail": "Reviewer rationale is nonblank and retains the required evidence concepts."}
    return {"score": 0, "detail": "Rationale is missing: " + ", ".join(missing) + "."}


def _table_rows(con: sqlite3.Connection, table: str, exclude_target: bool = False):
    con.row_factory = sqlite3.Row
    query = f"SELECT * FROM {table}"
    params = ()
    if exclude_target and table == "legal_lease_candidates":
        query += " WHERE candidate_id <> ?"
        params = (TARGET_ID,)
    rows = [dict(row) for row in con.execute(query, params)]
    return sorted(rows, key=lambda row: tuple((str(v) if v is not None else "") for v in row.values()))


def check_untouched_legal_records(ws):
    import hashlib
    import json

    expected_digests = {
        "legal_lease_candidates": "989f00e3daac46355022236757ab7a690b6b44c0a4ac5f9849cefcc462721942",
        "legal_contracts": "acbee552d23c727524a5e0d7eff5a7d5e9ea28e59bea991140ff49b3bf8c02bb",
        "contract_assets": "87766bb3562eeceb8933202713591d8f45be8e280f3608277c347197687e4975",
        "contract_amendments": "6d4558d4a357ea5a31fc3d9a78dcb5f62dd6f29d715effbc1db4c35db49fd120",
        "entity_spine": "e00026bbf9a64dd4f5e7463d78521ef685ca4527617cd3fbbc3d52027d2d7503",
    }
    tables = [
        ("legal_lease_candidates", True),
        ("legal_contracts", False),
        ("contract_assets", False),
        ("contract_amendments", False),
        ("entity_spine", False),
    ]
    with sqlite3.connect(_db_path(ws)) as current:
        for table, exclude_target in tables:
            rows = _table_rows(current, table, exclude_target)
            raw = json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
            digest = hashlib.sha256(raw).hexdigest()
            if digest != expected_digests[table]:
                return {"score": 0, "detail": f"Unexpected mutation detected in {table}."}
    return {"score": 1, "detail": "Non-target legal candidates and legal contract/index rows are unchanged."}
